def _fourth_client(model: dict) -> dict:
    """The five-zone architecture with a tablet beside the web and iOS clients, so four sockets meet one gateway."""
    more = json.loads(json.dumps(model))
    more["nodes"].insert(2, {"id": "tablet", "label": "Tablet client", "kind": "client", "zone": "client"})
    more["edges"].insert(2, {"from": "tablet", "to": "api", "label": "Live socket", "twoWay": True})
    more["expect"] = {"nodes": model["expect"]["nodes"] + 1, "connectors": model["expect"]["connectors"] + 1}
    return more


# Four sockets meet a gateway that has four magnets, each held by one of its own edges: the one left over arrives
# at a magnet another socket arrives at, instead of looping over the Clients zone to reach a free one.
MODELS["an architecture with four clients on one gateway"] = _fourth_client(
    RERUN["a five-zone architecture whose iOS socket detours along a zone border and whose two sync exits share one stub"])


def _accented(model: dict, *ids: str) -> dict:
    """The same board with its accent on the named nodes, messages (by number) or tasks."""
    marked = json.loads(json.dumps(model))
    for node in marked.get("nodes", []):
        if node["id"] in ids:
            node["accent"] = True
    for k, message in enumerate(marked.get("messages", []), 1):
        if str(k) in ids:
            message["accent"] = True
    for section in marked.get("sections", []):
        for task in section["tasks"]:
            if (task["id"] or task["name"]) in ids:
                task["accent"] = True
    return marked


# The accent lands on the node, message or task the first glance names, whatever kind that is.
MODELS["a user flow whose goal carries the accent"] = _accented(
    RERUN["a user flow with a goal and a start pill and no accent"], "confirmed")
MODELS["an architecture whose sync service carries the accent"] = _accented(
    RERUN["a five-zone architecture whose iOS socket detours along a zone border and whose two sync exits share one stub"], "sync")
MODELS["an ER diagram whose booking carries the accent"] = _accented(
    RERUN["an ER diagram whose edges ride a zone border, share trunks and print a label at a junction"], "Booking")
MODELS["a state machine whose pending state carries the accent"] = _accented(
    RERUN["a state machine whose two decisions leave one stub"], "Pending")
MODELS["a sequence whose async message carries the accent"] = _accented(
    RERUN["a sequence whose async message crosses a lifeline"], "6")
MODELS["a gantt chart whose critical task carries the accent"] = _accented(
    MODELS["a gantt chart with one critical task"], "integrate")
